#!/bin/bash
# Box 2 of rudb#1828 on gamingpc. W holds bench/ (rudb-bench at main), bin/ (rudb, rudb-bench, clickhouse) and data/tpch/sf<scale>, generated by `rudb-bench generate tpch --scale <n> --yes` with RUDB_BENCH_DUCKDB set to DuckDB 1.5.5. TPC-H at SCALE (1 or 10) from data/tpch/sf<scale>, one engine at a time on the P-cores, 1 cold and 3 hot tries per query, median of the hot tries read from the progress lines. Runs as root because the harness drops the page cache before each query.
set -u
W=${W:-/home/gopher/c0-gpc}
cd $W
SCALE=${SCALE:?set SCALE to 1 or 10}
mkdir -p out/tpch-sf$SCALE scratch
export RUDB_BENCH_DATA=$W/data RUDB_BENCH_RUDB=$W/bin/rudb RUDB_BENCH_CLICKHOUSE=$W/bin/clickhouse \
  RUDB_BENCH_STORED_ANSWERS=off RUDB_BENCH_SCRATCH=$W/scratch \
  RUDB_BENCH_THREADS=16 RUDB_BENCH_MEMORY=20GiB RUDB_BENCH_LOAD_LIMIT=2 RUDB_BENCH_LOAD_WAIT=14400 RUDB_BENCH_PROGRESS=1
CPUS=0-15
( while sleep 10; do echo "$(date +%s) $(cut -d" " -f1-3 /proc/loadavg) gpu $(nvidia-smi --query-gpu=utilization.gpu,memory.used --format=csv,noheader,nounits 2>/dev/null | tr -d ' ')"; done ) >> out/tpch-sf$SCALE/load.log &
SAMPLER=$!
for engine in ${ENGINES:-clickhouse-server duckdb rudb}; do
  echo "$(date -u) $engine start, $(df -h $W | tail -1), load $(cut -d" " -f1-3 /proc/loadavg)" >> out/tpch-sf$SCALE/progress.log
  ( cd bench && taskset -c $CPUS ../bin/rudb-bench run tpch --scale $SCALE --engines $engine --runs 4 --protocol upstream --timeout 600 --report ) 2>&1 \
    | while IFS= read -r line; do echo "$(date +%s) $line"; done > out/tpch-sf$SCALE/$engine.harness.log
  cp "$(ls -t bench/reports/*/run-tpch-*.md | head -1)" out/tpch-sf$SCALE/$engine.run.md 2>/dev/null
  for dir in scratch/rudb-bench-*; do [ -e "$dir" ] && rm -rf "$dir"; done
  echo "$(date -u) $engine done, scratch cleared, $(df -h $W | tail -1)" >> out/tpch-sf$SCALE/progress.log
done
kill $SAMPLER
touch out/tpch-sf$SCALE/DONE
